test "cross" {
    const garden = [_][]const u8{
        "  *  ", //
        "  *  ", //
        "*****", //
        "  *  ", //
        "  *  ", //
    };
    const expected = [_][]const u8{
        " 2*2 ", //
        "25*52", //
